import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Executive summary","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/EXECUTIVE-SUMMARY.html"}],["meta",{"property":"og:title","content":"Executive summary | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/EXECUTIVE-SUMMARY.html"}],["meta",{"name":"twitter:title","content":"Executive summary | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/EXECUTIVE-SUMMARY.md","filePath":"audits/EXECUTIVE-SUMMARY.md","lastUpdated":1794198491000}`),a={name:`audits/EXECUTIVE-SUMMARY.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to “Executive summary”">​</a></h1><p><strong>Re-audited source:</strong> <code>dev</code> at <code>caccaf26b4415ae783959e888ff45e33becdadf6</code><br><strong>Ruleset:</strong> <a href="https://github.com/aaron-fredrick/RULESETS" target="_blank" rel="noreferrer">RULESETS</a> <code>main</code> at <code>79d7dd4f0c0d544ba85abeb19286ef2cae34bf89</code><br><strong>Review type:</strong> Static engineering re-audit after PRs <a href="https://github.com/aaron-fredrick/FD-Calculator/pull/75" target="_blank" rel="noreferrer">#75</a> and <a href="https://github.com/aaron-fredrick/FD-Calculator/pull/80" target="_blank" rel="noreferrer">#80</a>. Status and remaining work are recorded in the <a href="./IMPLEMENTATION-PLAN.html">implementation plan</a>.</p><h2 id="overall-assessment" tabindex="-1">Overall assessment <a class="header-anchor" href="#overall-assessment" aria-label="Permalink to “Overall assessment”">​</a></h2><p>FD Cal has a solid foundation: the browser and CLI share the JavaScript engine; the browser calculation runs in a dedicated worker; the configuration shape is explicitly validated; reporting escapes most dynamic text; the standalone report is self-contained; search diagnostics expose pruning and optimality status; and the test suite includes financial, strategy-parity, worker-contract, reporting and workflow-contract coverage.</p><p>The remediation pass has closed the two highest-risk defects: imported account IDs are now encoded at the DOM boundary, and result output distinguishes pre-withdrawal value from closing assets/liabilities/net worth. Absolute R+ now has finite browser defaults, cooperative time limits, cancellation and a worker watchdog. Bank source status/review dates are visible. The dev web/docs publishers are now independent.</p><p>The remaining material gaps are installment-product contract semantics, static-hosting security-header policy, and browser-level QA. Crawler controls are in place: the production sitemap includes the canonical root and <code>/web/</code> URLs, while preview output is excluded and marked noindex. The <code>dev</code> deployment pipeline now composes the preview under <code>/dev/</code>; porting that preservation behaviour to <code>main</code> is deliberately outside this pass and will be revisited when work moves to <code>main</code>. The project is still not financially certified or fully accessibility-verified.</p><h2 id="priority-findings" tabindex="-1">Priority findings <a class="header-anchor" href="#priority-findings" aria-label="Permalink to “Priority findings”">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Current status</th><th>Main location</th></tr></thead><tbody><tr><td>SEC-01</td><td><strong>P1</strong></td><td>Imported account IDs reached HTML attributes without encoding</td><td><strong>Completed</strong> — PR #75</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/web/app.js" target="_blank" rel="noreferrer">app.js</a></td></tr><tr><td>FIN-01</td><td><strong>P1</strong></td><td>Pre-withdrawal value was presented as closing portfolio value</td><td><strong>Completed</strong> — PR #75</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/core/results.js" target="_blank" rel="noreferrer">results.js</a></td></tr><tr><td>FIN-02</td><td><strong>P2</strong></td><td>Capital contributed was described as capital invested</td><td><strong>Completed</strong> — PR #75</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/web/app.js" target="_blank" rel="noreferrer">app.js</a></td></tr><tr><td>FIN-03</td><td><strong>P2</strong></td><td>Product-level source provenance in reports</td><td><strong>Implemented on this branch; CI passed, pending dev shipment</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/reporting/html.js" target="_blank" rel="noreferrer">html.js</a></td></tr><tr><td>ENG-01</td><td><strong>P2</strong></td><td>Installment payments may extend beyond nominal maturity</td><td><strong>Partial</strong> — event order tested; product contract open</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/core/models.js" target="_blank" rel="noreferrer">models.js</a></td></tr><tr><td>ENG-02</td><td><strong>P2</strong></td><td>Elapsed-day interest uses the start-year 365/366 denominator</td><td><strong>Partial</strong> — convention documented; source verification open</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/core/interest.js" target="_blank" rel="noreferrer">interest.js</a></td></tr><tr><td>ENG-03</td><td><strong>P2</strong></td><td>Financial product invariants are distributed across model/load boundaries</td><td><strong>Open</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/core/models.js" target="_blank" rel="noreferrer">models.js</a></td></tr><tr><td>ENG-04</td><td><strong>P2</strong></td><td>AIT is a fixed 10% engine assumption</td><td><strong>Open</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/core/configuration.js" target="_blank" rel="noreferrer">configuration.js</a></td></tr><tr><td>ENG-05</td><td><strong>P1/P2</strong></td><td>Result value semantics were ambiguous around outflows</td><td><strong>Completed</strong> — covered by FIN-01</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/core/results.js" target="_blank" rel="noreferrer">results.js</a></td></tr><tr><td>SEARCH-01</td><td><strong>P2</strong></td><td>Browser Absolute R+ lacked finite default budgets and a post-start timeout</td><td><strong>Implemented</strong> — benchmark calibration pending</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/strategies/search-strategy-base.js" target="_blank" rel="noreferrer">search-strategy-base.js</a></td></tr><tr><td>SEARCH-02</td><td><strong>P3</strong></td><td>Large strategy modules concentrate independent responsibilities</td><td><strong>Open</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/strategies/search-strategy-base.js" target="_blank" rel="noreferrer">search-strategy-base.js</a></td></tr><tr><td>SEARCH-03</td><td><strong>P2/P3</strong></td><td>Independent planner logic needs continued runtime/parity protection</td><td><strong>Open / ongoing control</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/strategies/gss.js" target="_blank" rel="noreferrer">gss.js</a></td></tr><tr><td>DATA-01</td><td><strong>P2</strong></td><td>Product-level source URL, effective date and caveat disclosure</td><td><strong>Implemented on this branch; CI passed, pending dev shipment</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/web/app.js" target="_blank" rel="noreferrer">app.js</a></td></tr><tr><td>DATA-02</td><td><strong>Scope boundary</strong></td><td>Senior/minor toggles do not verify depositor eligibility</td><td><strong>Closed as owner-confirmed scope</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/core/configuration.js" target="_blank" rel="noreferrer">configuration.js</a></td></tr><tr><td>DATA-03</td><td><strong>Deferred</strong></td><td>Active FD model does not represent all special-product constraints</td><td><strong>Deferred</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/core/models.js" target="_blank" rel="noreferrer">models.js</a></td></tr><tr><td>DATA-04</td><td><strong>P3</strong></td><td>CSV parser did not enforce exact row field counts or strict quote placement</td><td><strong>Implemented on this branch; CI passed, pending dev shipment</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/io/csv.js" target="_blank" rel="noreferrer">csv.js</a></td></tr><tr><td>DATA-05</td><td><strong>P2/P3</strong></td><td>Transfer fees are not a full transfer-channel model</td><td><strong>Open / documented limitation</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/data/banks/banks.csv" target="_blank" rel="noreferrer">banks.csv</a></td></tr><tr><td>DATA-06</td><td><strong>P2</strong></td><td>Rate freshness and secondary-source warning policy is incomplete</td><td><strong>Partial</strong></td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/data/fd_options/fd_options.csv" target="_blank" rel="noreferrer">fd_options.csv</a></td></tr><tr><td>DEPLOY-01</td><td><strong>P2</strong></td><td>Dev Pages assembly must retain the <code>/dev/</code> preview subtree</td><td><strong>Completed on <code>dev</code></strong> — independent dev publishers and assembler are present; <code>main</code> port deferred</td><td><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/.github/workflows/pages.yml" target="_blank" rel="noreferrer">pages.yml</a></td></tr></tbody></table><p>| UI-01 | <strong>P3</strong> | Programmatic scrolling must respect reduced-motion preference | <strong>Implemented on this branch; CI passed, pending dev shipment</strong> | <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/web/motion.js" target="_blank" rel="noreferrer">motion.js</a> | | UI-02 | <strong>P3</strong> | Help tooltip needs programmatic content and touch operation | <strong>Implemented on this branch; CI passed, pending dev shipment</strong> | <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/web/app.js" target="_blank" rel="noreferrer">app.js</a> | | UI-03 | <strong>P3</strong> | Inline validation errors need programmatic field association | <strong>Implemented on this branch; CI passed, pending dev shipment</strong> | <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/web/app.js" target="_blank" rel="noreferrer">app.js</a> | | PRIV-01 | <strong>P2/P3</strong> | Local drafts need a user-facing deletion/retention control | <strong>Implemented on this branch; CI passed, pending dev shipment</strong> | <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/web/app.js" target="_blank" rel="noreferrer">app.js</a> | | WEB-SEC-02 | <strong>P2/P3</strong> | Static hosting has no verified response-header strategy | <strong>Open / hosting constraint</strong> | <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/docs/audits/SECURITY-PRIVACY.md" target="_blank" rel="noreferrer">SECURITY-PRIVACY.md</a> | | QA-01 | <strong>Deferred</strong> | No automated real-browser end-to-end suite | <strong>Deferred</strong> | <a href="https://github.com/aaron-fredrick/FD-Calculator/tree/dev/tests" target="_blank" rel="noreferrer">tests/</a> | | QA-REP-01 | <strong>P3</strong> | Downloaded standalone HTML has not been independently browser-tested | <strong>Open</strong> | <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/dev/src/reporting/html.js" target="_blank" rel="noreferrer">html.js</a> |</p><h2 id="owner-feedback-and-decisions" tabindex="-1">Owner feedback and decisions <a class="header-anchor" href="#owner-feedback-and-decisions" aria-label="Permalink to “Owner feedback and decisions”">​</a></h2><table tabindex="0"><thead><tr><th>Finding</th><th>Decision / interpretation</th><th>Planned treatment</th></tr></thead><tbody><tr><td><strong>SEC-01</strong></td><td>Confirmed valid finding</td><td><strong>Completed in PR #75.</strong> IDs are HTML-attribute encoded without restricting their accepted identity; adversarial regression coverage added.</td></tr><tr><td><strong>FIN-01</strong></td><td>Confirmed overlooked result-presentation issue</td><td><strong>Completed in PR #75.</strong> Explicit pre-withdrawal, closing-assets, outstanding-liability and closing-net-worth metrics are exposed; runtime settlement and strategy objective remain unchanged.</td></tr><tr><td><strong>ENG-01</strong></td><td>Event order is intentional: cash inflows/FD cash flows first, outflows second, decision third</td><td>Preserve and test this order. It does not alone determine whether a final installment after nominal maturity matches a bank contract. Do not clamp dates until representative product terms establish the correct model.</td></tr><tr><td><strong>ENG-02</strong></td><td>Project intends an actual elapsed-day/relative-delta basis</td><td>Keep the current formula for now; document the exact start-year 365/366 denominator and verify against representative bank terms before changing financial calculations.</td></tr><tr><td><strong>SEARCH-01</strong></td><td>Finite defaults are required, but users may opt into unlimited work</td><td><strong>Implemented in PR #75.</strong> Browser defaults are 10,000 expanded states and 30 seconds; explicit unlimited controls, cooperative stopping, cancellation, watchdog and diagnostics are present. Benchmark calibration remains.</td></tr><tr><td><strong>DATA-01</strong></td><td>Implemented on this branch</td><td>Bank-level review/status disclosure remains; product source URL, effective date, source type and caveat now flow through web/CLI loaders and worker results into HTML and console reports. Missing effective dates are explicitly shown as not recorded.</td></tr><tr><td><strong>DATA-02</strong></td><td>Eligibility verification is the user&#39;s responsibility; FD Cal is not a bank onboarding/security gate</td><td>Treat senior/minor toggles as inclusion filters. Retain a clear disclaimer; do not add age/guardian verification as part of this work.</td></tr><tr><td><strong>DATA-03</strong></td><td>Scope not yet clear</td><td>Defer until the owner specifies which special-product constraints should be modelled. Keep products with unenforced critical terms out of the active catalogue.</td></tr><tr><td><strong>DEPLOY-01</strong></td><td>Dev preview is intentionally public for users and contributors</td><td><strong>Completed for the current <code>dev</code> delivery path in PR #80.</strong> Separate dev web/docs artifacts are assembled under <code>/dev/</code>; preview HTML is noindex and the root crawler policy disallows the subtree. Porting the assembler to <code>main</code> is deferred until main-branch work begins.</td></tr></tbody></table><p>| <strong>DATA-04</strong> | Implemented on this branch | Inventoried all 33 catalogue CSVs, repaired 93 rows with unquoted comma-containing metadata across three files, and added strict row-width/quote validation with source and line diagnostics. CI verifies the full inventory. | | <strong>UI-01</strong> | Implemented on this branch | A shared scroll helper checks <code>prefers-reduced-motion</code> at each request; reduced-motion users receive <code>behavior: auto</code>, while normal users retain smooth scrolling. Unit coverage verifies both branches. | | <strong>QA-01</strong> | Needs owner decision | Finding means no automated real-browser E2E suite was found. Defer the choice between Playwright smoke coverage and manual browser verification. |</p><h2 id="positive-controls-worth-preserving" tabindex="-1">Positive controls worth preserving <a class="header-anchor" href="#positive-controls-worth-preserving" aria-label="Permalink to “Positive controls worth preserving”">​</a></h2><ul><li><strong>Shared engine:</strong> the browser worker and CLI call the same core strategy/simulation implementation.</li><li><strong>Runtime boundary:</strong> <code>SimulationRuntime</code> is the authoritative event processor and executor; strategies consume planning views and submit decisions.</li><li><strong>Outflow sequencing:</strong> same-date inflows, FD cash flows, and maturities are credited before outflows are settled; strategy decisions follow settlement.</li><li><strong>Input validation:</strong> configuration keys, data types, ranges and schedule relationships are checked before simulation.</li><li><strong>Worker protocol:</strong> the implementation correctly avoids using <code>event.origin</code> as authentication for a dedicated Worker and validates the message contract.</li><li><strong>Report output:</strong> dynamic report text is generally escaped; embedded JSON protects closing-script sequences; the report is self-contained.</li><li><strong>Strategy transparency:</strong> Absolute R+ exposes expanded states, beam pruning, budgets and optimality status.</li><li><strong>Regression base:</strong> tests include engine, cash-flow, configuration, provenance, strategy parity, worker, report and Pages workflow contracts.</li><li><strong>Privacy posture:</strong> no third-party analytics or session-replay instrumentation was identified in the reviewed application code; the UI says drafts remain in the browser.</li></ul><h2 id="recommended-implementation-order" tabindex="-1">Recommended implementation order <a class="header-anchor" href="#recommended-implementation-order" aria-label="Permalink to “Recommended implementation order”">​</a></h2><ol><li><strong>DATA-01 / FIN-03:</strong> implemented on this branch with worker, HTML report and CLI report coverage; pending dev shipment.</li><li><strong>ENG-01/ENG-02:</strong> validate installment and elapsed-day conventions against representative bank terms before changing financial calculations.</li><li><strong>DATA-04:</strong> implemented on this branch; all 33 catalogue CSVs pass strict row-width and quote validation, pending dev shipment.</li><li>Preserve crawler controls: keep <code>/dev/</code> excluded by the root robots policy, keep preview HTML noindex, and ensure the production sitemap contains canonical production routes only.</li><li><strong>UI-01/02/03:</strong> implemented on the working branch with contract/unit coverage; pending dev shipment and browser/assistive-technology verification.</li><li><strong>WEB-SEC-02:</strong> verify actual production/dev response headers and decide whether a CDN/proxy or hosting migration is needed. The GitHub Pages boundary is documented; PRIV-01 is implemented on this branch.</li><li><strong>QA-01 / QA-REP-01:</strong> decide on browser automation and verify the app/report in a real browser.</li><li><strong>Main integration (later):</strong> when work moves to <code>main</code>, port and verify the preview-aware assembler there; this is not a current <code>dev</code> blocker.</li></ol><p>DATA-02 is an accepted product-scope boundary. DATA-03 and QA-01 remain deferred for owner decisions. Detailed phases, regression cases, and non-regression gates are in <a href="./IMPLEMENTATION-PLAN.html">IMPLEMENTATION-PLAN.md</a>.</p><h2 id="release-and-verification-caveats" tabindex="-1">Release and verification caveats <a class="header-anchor" href="#release-and-verification-caveats" aria-label="Permalink to “Release and verification caveats”">​</a></h2><ul><li>The source audit is not formal financial verification, a penetration test, or bank-product certification.</li><li>The Node.js test/syntax workflow and independent dev web build passed on the exact audited <code>dev</code> commit; the dev docs/benchmark workflow was still running when checked. These checks do not prove rendered browser behaviour, screen-reader output, or financial-product correctness.</li><li>No manual browser, screen-reader, or full WCAG assessment was completed as part of the static audit.</li><li>The dev preview is a subtree of the same GitHub Pages site. Production and dev deployments must be serialized and both must preserve the other&#39;s published files.</li><li>PR #75 contains the security, result, search-budget and catalogue-disclosure implementation now merged to <code>dev</code>; PR #80 contains the dev publishing split now merged to <code>dev</code>.</li><li>This re-audit commit updates documentation only. No new application behaviour is changed here.</li></ul>`,19)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};